#ifndef HB_AAT_LAYOUT_COMMON_HH
#define HB_AAT_LAYOUT_COMMON_HH

#include "hb-aat-layout.hh"


namespace AAT {

using namespace OT;


/*
 * Lookup Table
 */

template <typename T> struct Lookup;

template <typename T>
struct LookupFormat0
{
  friend struct Lookup<T>;

  private:
  inline const T* get_value (hb_codepoint_t glyph_id, unsigned int num_glyphs) const
  {
    if (unlikely (glyph_id >= num_glyphs)) return nullptr;
    return &arrayZ[glyph_id];
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (arrayZ.sanitize (c, c->get_num_glyphs ()));
  }

  protected:
  HBUINT16      format;         /* Format identifier--format = 0 */
  UnsizedArrayOf<T>
                arrayZ;         /* Array of lookup values, indexed by glyph index. */
  public:
  DEFINE_SIZE_ARRAY (2, arrayZ);
};


template <typename T>
struct LookupSegmentSingle
{
  inline int cmp (hb_codepoint_t g) const {
    return g < first ? -1 : g <= last ? 0 : +1 ;
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) && value.sanitize (c));
  }

  GlyphID       last;           /* Last GlyphID in this segment */
  GlyphID       first;          /* First GlyphID in this segment */
  T             value;          /* The lookup value (only one) */
  public:
  DEFINE_SIZE_STATIC (4 + T::static_size);
};

template <typename T>
struct LookupFormat2
{
  friend struct Lookup<T>;

  private:
  inline const T* get_value (hb_codepoint_t glyph_id) const
  {
    const LookupSegmentSingle<T> *v = segments.bsearch (glyph_id);
    return v ? &v->value : nullptr;
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (segments.sanitize (c));
  }

  protected:
  HBUINT16      format;         /* Format identifier--format = 2 */
  VarSizedBinSearchArrayOf<LookupSegmentSingle<T> >
                segments;       /* The actual segments. These must already be sorted,
                                 * according to the first word in each one (the last
                                 * glyph in each segment). */
  public:
  DEFINE_SIZE_ARRAY (8, segments);
};

template <typename T>
struct LookupSegmentArray
{
  inline const T* get_value (hb_codepoint_t glyph_id, const void *base) const
  {
    return first <= glyph_id && glyph_id <= last ? &(base+valuesZ)[glyph_id - first] : nullptr;
  }

  inline int cmp (hb_codepoint_t g) const {
    return g < first ? -1 : g <= last ? 0 : +1 ;
  }

  inline bool sanitize (hb_sanitize_context_t *c, const void *base) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) &&
                  first <= last &&
                  valuesZ.sanitize (c, base, last - first + 1));
  }

  GlyphID       last;           /* Last GlyphID in this segment */
  GlyphID       first;          /* First GlyphID in this segment */
  OffsetTo<UnsizedArrayOf<T>, HBUINT16, false>
                valuesZ;        /* A 16-bit offset from the start of
                                 * the table to the data. */
  public:
  DEFINE_SIZE_STATIC (6);
};

template <typename T>
struct LookupFormat4
{
  friend struct Lookup<T>;

  private:
  inline const T* get_value (hb_codepoint_t glyph_id) const
  {
    const LookupSegmentArray<T> *v = segments.bsearch (glyph_id);
    return v ? v->get_value (glyph_id, this) : nullptr;
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (segments.sanitize (c, this));
  }

  protected:
  HBUINT16      format;         /* Format identifier--format = 4 */
  VarSizedBinSearchArrayOf<LookupSegmentArray<T> >
                segments;       /* The actual segments. These must already be sorted,
                                 * according to the first word in each one (the last
                                 * glyph in each segment). */
  public:
  DEFINE_SIZE_ARRAY (8, segments);
};

template <typename T>
struct LookupSingle
{
  inline int cmp (hb_codepoint_t g) const { return glyph.cmp (g); }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) && value.sanitize (c));
  }

  GlyphID       glyph;          /* Last GlyphID */
  T             value;          /* The lookup value (only one) */
  public:
  DEFINE_SIZE_STATIC (2 + T::static_size);
};

template <typename T>
struct LookupFormat6
{
  friend struct Lookup<T>;

  private:
  inline const T* get_value (hb_codepoint_t glyph_id) const
  {
    const LookupSingle<T> *v = entries.bsearch (glyph_id);
    return v ? &v->value : nullptr;
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (entries.sanitize (c));
  }

  protected:
  HBUINT16      format;         /* Format identifier--format = 6 */
  VarSizedBinSearchArrayOf<LookupSingle<T> >
                entries;        /* The actual entries, sorted by glyph index. */
  public:
  DEFINE_SIZE_ARRAY (8, entries);
};

template <typename T>
struct LookupFormat8
{
  friend struct Lookup<T>;

  private:
  inline const T* get_value (hb_codepoint_t glyph_id) const
  {
    return firstGlyph <= glyph_id && glyph_id - firstGlyph < glyphCount ?
           &valueArrayZ[glyph_id - firstGlyph] : nullptr;
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    return_trace (c->check_struct (this) && valueArrayZ.sanitize (c, glyphCount));
  }

  protected:
  HBUINT16      format;         /* Format identifier--format = 8 */
  GlyphID       firstGlyph;     /* First glyph index included in the trimmed array. */
  HBUINT16      glyphCount;     /* Total number of glyphs (equivalent to the last
                                 * glyph minus the value of firstGlyph plus 1). */
  UnsizedArrayOf<T>
                valueArrayZ;    /* The lookup values (indexed by the glyph index
                                 * minus the value of firstGlyph). */
  public:
  DEFINE_SIZE_ARRAY (6, valueArrayZ);
};

template <typename T>
struct Lookup
{
  inline const T* get_value (hb_codepoint_t glyph_id, unsigned int num_glyphs) const
  {
    switch (u.format) {
    case 0: return u.format0.get_value (glyph_id, num_glyphs);
    case 2: return u.format2.get_value (glyph_id);
    case 4: return u.format4.get_value (glyph_id);
    case 6: return u.format6.get_value (glyph_id);
    case 8: return u.format8.get_value (glyph_id);
    default:return nullptr;

---KERX---
      Reset             = 0x2000,       /* If set, reset the kerning data (clear the stack) */
      Reserved          = 0x1FFF,       /* Not used; set to 0. */
    };

    inline driver_context_t (const KerxSubTableFormat1 *table,
                             hb_aat_apply_context_t *c_) :
        c (c_),
        /* Apparently the offset kernAction is from the beginning of the state-machine,
         * similar to offsets in morx table, NOT from beginning of this table, like
         * other subtables in kerx.  Discovered via testing. */
        kernAction (&table->machine + table->kernAction),
        depth (0) {}

    inline bool is_actionable (StateTableDriver<EntryData> *driver,
                               const Entry<EntryData> *entry)
    {
      return entry->data.kernActionIndex != 0xFFFF;
    }
    inline bool transition (StateTableDriver<EntryData> *driver,
                            const Entry<EntryData> *entry)
    {
      hb_buffer_t *buffer = driver->buffer;
      unsigned int flags = entry->flags;

      if (flags & Reset)
      {
        depth = 0;
      }

      if (flags & Push)
      {
        if (likely (depth < ARRAY_LENGTH (stack)))
          stack[depth++] = buffer->idx;
        else
          depth = 0; /* Probably not what CoreText does, but better? */
      }

      if (entry->data.kernActionIndex != 0xFFFF)
      {
        const FWORD *actions = &kernAction[entry->data.kernActionIndex];
        if (!c->sanitizer.check_array (actions, depth))
        {
          depth = 0;
          return false;
        }

        hb_mask_t kern_mask = c->plan->kern_mask;
        for (unsigned int i = 0; i < depth; i++)
        {
          /* Apparently, when spec says "Each pops one glyph from the kerning stack
           * and applies the kerning value to it.", it doesn't mean it in that order.
           * The deepest item in the stack corresponds to the first item in the action
           * list.  Discovered by testing. */
          unsigned int idx = stack[i];
          int v = *actions++;
          if (idx < buffer->len && buffer->info[idx].mask & kern_mask)
          {
            /* XXX Non-forward direction... */
            if (HB_DIRECTION_IS_HORIZONTAL (buffer->props.direction))
              buffer->pos[idx].x_advance += c->font->em_scale_x (v);
            else
              buffer->pos[idx].y_advance += c->font->em_scale_y (v);
          }
        }
        depth = 0;
      }

      return true;
    }

    private:
    hb_aat_apply_context_t *c;
    const UnsizedArrayOf<FWORD> &kernAction;
    unsigned int stack[8];
    unsigned int depth;
  };

  inline bool apply (hb_aat_apply_context_t *c) const
  {
    TRACE_APPLY (this);

    if (!c->plan->requested_kerning)
      return false;

    driver_context_t dc (this, c);

    StateTableDriver<EntryData> driver (machine, c->buffer, c->font->face);
    driver.drive (&dc);

    return_trace (true);
  }

  inline bool sanitize (hb_sanitize_context_t *c) const
  {
    TRACE_SANITIZE (this);
    /* The rest of array sanitizations are done at run-time. */
    return_trace (likely (c->check_struct (this) &&
                          machine.sanitize (c)));
  }

  protected:

---MORX---
                                         * if the glyph at that index has changed. */
      MarkLast          = 0x2000,       /* If set, make the current glyph the last
                                         * glyph to be rearranged. */
      Reserved          = 0x1FF0,       /* These bits are reserved and should be set to 0. */
      Verb              = 0x000F,       /* The type of rearrangement specified. */
    };

    inline driver_context_t (const RearrangementSubtable *table) :
        ret (false),
        start (0), end (0) {}

    inline bool is_actionable (StateTableDriver<EntryData> *driver,
                               const Entry<EntryData> *entry)
    {
      return (entry->flags & Verb) && start < end;
    }
    inline bool transition (StateTableDriver<EntryData> *driver,
                            const Entry<EntryData> *entry)
    {
      hb_buffer_t *buffer = driver->buffer;
      unsigned int flags = entry->flags;

      if (flags & MarkFirst)
        start = buffer->idx;

      if (flags & MarkLast)
        end = MIN (buffer->idx + 1, buffer->len);

      if ((flags & Verb) && start < end)
      {
        /* The following map has two nibbles, for start-side
         * and end-side. Values of 0,1,2 mean move that many
         * to the other side. Value of 3 means move 2 and
         * flip them. */
        const unsigned char map[16] =
        {
          0x00, /* 0    no change */
          0x10, /* 1    Ax => xA */
          0x01, /* 2    xD => Dx */
          0x11, /* 3    AxD => DxA */
          0x20, /* 4    ABx => xAB */
          0x30, /* 5    ABx => xBA */
          0x02, /* 6    xCD => CDx */
          0x03, /* 7    xCD => DCx */
          0x12, /* 8    AxCD => CDxA */
          0x13, /* 9    AxCD => DCxA */
          0x21, /* 10   ABxD => DxAB */
          0x31, /* 11   ABxD => DxBA */
          0x22, /* 12   ABxCD => CDxAB */
          0x32, /* 13   ABxCD => CDxBA */
          0x23, /* 14   ABxCD => DCxAB */
          0x33, /* 15   ABxCD => DCxBA */
        };

        unsigned int m = map[flags & Verb];
        unsigned int l = MIN<unsigned int> (2, m >> 4);
        unsigned int r = MIN<unsigned int> (2, m & 0x0F);
        bool reverse_l = 3 == (m >> 4);
        bool reverse_r = 3 == (m & 0x0F);

        if (end - start >= l + r)
